public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int l = in.nextInt();
        int n = in.nextInt();
        int engKichik = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int mtu = in.nextInt();
            if (mtu < engKichik) {
                engKichik = mtu;
            }
        }
        int qism = (engKichik - 20) / 8 * 8;
        int soni = (l + qism - 1) / qism;
        System.out.println(qism + " " + soni);
    }
}

